/** The symbol: a coral C completed by a leaf. Decorative unless a label is given. */
export function BrandSymbol({ size = 34, label }: { size?: number; label?: string }) {
  const cut = size <= 32 ? SYMBOL.small : SYMBOL.master;
  return (
    <svg
      className="brand-symbol"
      viewBox="0 0 256 256"
      width={size}
      height={size}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      <path className="brand-fruit" d={cut.fruit} />
      <path className="brand-leaf" d={cut.leaf} />
    </svg>
  );
}

/** The FRESH CHOICE wordmark (custom capitals, drawn as outlines). `height` is the cap height in px. */
export function BrandWordmark({ height = 13, label = 'Fresh Choice' }: { height?: number; label?: string }) {
  return (
    <svg
      className="brand-wordmark"
      viewBox={`0 0 ${WORDMARK.width} ${WORDMARK.height}`}
      width={Math.round((WORDMARK.width / WORDMARK.height) * height)}
      height={height}
      role="img"
      aria-label={label}
      focusable="false"
    >
      <path d={WORDMARK.d} />
    </svg>
  );
}
